'use strict';
const esc=LumiereProfile.escapeHTML;
const svg={menu:'M4 6h16M4 12h16M4 18h16',x:'m6 6 12 12M6 18 18 6',arrow:'M4 12h16m-6-6 6 6-6 6',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',moon:'M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11Z',bottle:'M8 3h8v4H8zM9 7v3l-3 3v8h12v-8l-3-3V7M9 15h6',scan:'M8 3H3v5m13-5h5v5M3 16v5h5m8 0h5v-5M9 9h.1M15 9h.1M9 15q3 3 6 0',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',chart:'M4 3v17h17M7 15l4-4 4 2 5-7',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',shield:'m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6l8-3Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chevron:'m9 5 7 7-7 7',camera:'M8 5h8l2 3h3v12H3V8h3l2-3ZM9 13a3 3 0 1 0 6 0 3 3 0 1 0-6 0',check:'m5 12 4 4L19 6',heart:'M12 21 3 12C-3 3 9 0 12 7c3-7 15-4 9 5Z',calendar:'M3 5h18v16H3zM7 3v4m10-4v4M3 10h18',pin:'M19 9c0 6-7 12-7 12S5 15 5 9a7 7 0 1 1 14 0Z',chat:'M21 11a9 9 0 0 1-13 8l-5 2 2-5a9 9 0 1 1 16-5Z',user:'M8 8a4 4 0 1 0 8 0 4 4 0 1 0-8 0M4 21v-2a8 8 0 0 1 16 0v2',drop:'M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z',edit:'m14 5 5 5M4 20l5-1L21 7l-5-5L4 14v6Z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${svg[n]||svg.spark}"/>${n==='sun'?'<circle cx="12" cy="12" r="4"/>':''}</svg>`;
const $=s=>document.querySelector(s);
let state=null,token='',catalog=[],sources=[],status=null,photo=null,chatBusy=false,chatDraft='',photoBusy=false,stream=null;
let period=new Date().getHours()>=18||new Date().getHours()<6?'evening':'morning';
let metric='comfort',span=30,filter='All';
const main=$('#main'),dialog=$('#detail-dialog');
const name=()=>state.profile?.name||'Jamie Chan';
const day=()=>new Intl.DateTimeFormat('en-CA',{timeZone:state.settings.timezone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const shortDate=d=>new Date(d).toLocaleDateString('en',{month:'short',day:'numeric'});
const longDate=d=>new Date(d).toLocaleString('en',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});
const route=()=>location.hash.slice(1)||'overview';
const button=(label,action,extra='',style='plum')=>`<button class="button ${style}" data-action="${action}" ${extra}>${label}</button>`;
const link=(label,page)=>`<a class="text-link" href="#${page}">${label}${icon('arrow')}</a>`;
const intro=(eyebrow,title,extra='')=>`<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1></div>${extra}</div>`;
const empty=(title,copy,action='')=>`<div class="empty-state">${icon('spark')}<h3>${title}</h3><p>${copy}</p>${action}</div>`;
const options=(list,value)=>list.map(v=>`<option value="${esc(v)}"${v===value?' selected':''}>${esc(v)}</option>`).join('');
const field=(label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(label,name,list,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options(list,value)}</select></label>`;
const textarea=(label,name,value='',max=600)=>`<label class="field span-two"><span>${label}</span><textarea name="${name}" maxlength="${max}" rows="3">${esc(value)}</textarea></label>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Lumiere-Token':token},body:data===undefined?undefined:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed.');if(d.state)state=d.state;return d;}
function modal(title,content){$('#dialog-content').innerHTML=`<span class="eyebrow">YOUR LUMIÈRE</span><h2 id="dialog-title">${title}</h2>${content}`;if(!dialog.open)dialog.showModal();}
function closeModal(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}dialog.close();}
function navClose(){ $('.sidebar').classList.remove('open');$('.sidebar').inert=true;$('.nav-backdrop').hidden=true;$('.workspace').inert=false;$('.menu-toggle').setAttribute('aria-expanded','false');}
function navOpen(){ $('.sidebar').inert=false;$('.sidebar').classList.add('open');$('.nav-backdrop').hidden=false;$('.workspace').inert=true;$('.menu-toggle').setAttribute('aria-expanded','true');$('.sidebar-close').focus();}
function identity(){document.querySelectorAll('[data-profile-name]').forEach(e=>e.textContent=name());document.querySelectorAll('[data-profile-initial]').forEach(e=>e.textContent=Array.from(name())[0]);$('.notification-button i').hidden=!state.notifications.some(n=>!n.read);}
function tabs(all=false){return `<div class="tabs period-tabs" aria-label="Routine time">${[['morning','sun','Morning'],['evening','moon','Evening'],...(all?[['all','grid','Overview']]:[])].map(([p,i,label])=>`<button data-period="${p}" class="${period===p?'active':''}" aria-pressed="${period===p}">${icon(i)}${label}</button>`).join('')}</div>`;}
function remaining(p){if(p.status==='finished')return 0;const days=p.status==='using'?Math.max(0,(Date.now()-Date.parse(p.remainingAt||p.start))/86400000):0;return Math.round(Math.max(0,Math.min(100,p.remaining-days*100/p.cycleDays)));}
function bottle(p,large=false){return `<div class="bottle-art ${esc(p.type.toLowerCase())} ${large?'large':''}" aria-label="Estimated ${remaining(p)} percent remaining"><div class="bottle-cap"></div><div class="bottle-body"><div class="bottle-fill" style="height:${remaining(p)}%"></div><span class="bottle-label">${icon(p.type==='Sunscreen'?'sun':'drop')}<b>${esc(p.type)}</b><small>LUMIÈRE SHELF</small></span></div></div>`;}
function onboarding(){return `<section class="welcome"><div class="welcome-copy"><span class="eyebrow">WELCOME TO YOUR SKINCARE SPACE</span><h1>Good care begins<br>with <em>understanding you.</em></h1><p>No perfect skincare words. No complicated routine.<br>Tell Lumière how your skin feels, and take one small step.</p><div class="welcome-actions"><a class="button plum" href="#profile">Set up my local profile ${icon('arrow')}</a><a class="button outline" href="#checkin">Start with a photo</a></div><span class="muted">Private, local AI · You choose what to save</span></div><div class="welcome-portrait"><img src="assets/skincare-portrait.png" alt="Beauty portrait in soft daylight"><span>YOUR SKIN. YOUR OWN PACE.</span></div></section><div class="welcome-foot"><p>Already know your way around?</p>${button('Open my dressing table','skip','','outline')}<button class="welcome-help-link" data-action="start">Help me understand my skin</button></div>`;}
function overview(){if(!state.settings.onboarded)return onboarding();const evening=period==='evening';return `${intro('YOUR DAILY MOMENT',`${evening?'Good evening':'Hello'}, ${esc(name().split(' ')[0])}.`,tabs())}
 <section class="dressing-table ${evening?'night':''}" aria-label="Your interactive dressing table">
  <a class="window-scene" href="#weather"><span class="window-frame"><i class="sky-orb"></i><i class="window-horizon"></i></span><span class="scene-label">${icon(evening?'moon':'sun')}By the window<small>${state.weather?`${esc(state.weather.city.name)} · ${state.weather.temperature}°C`:'Weather & today’s care'}${icon('arrow')}</small></span></a>
  <div class="wall-glow"></div><a href="#checkin" class="vanity-mirror"><div class="mirror-inner"><span class="mirror-star">✧</span>${icon('scan')}<h2>A moment<br>to check in.</h2><span>OPEN YOUR SKIN MIRROR ${icon('arrow')}</span></div></a>
  <button class="vanity-products am" data-action="shelf-am"><div class="decor-bottles"><i></i><i></i><i></i></div><span>${icon('sun')}Morning care<small>Your everyday essentials</small></span></button>
  <button class="vanity-products pm" data-action="shelf-pm"><div class="decor-bottles"><i></i><i></i></div><span>${icon('moon')}Evening care<small>A gentle end to the day</small></span></button>
  <div class="table-surface"></div><div class="table-front"><i></i><i></i></div><span class="scene-caption">A LITTLE SPACE, JUST FOR YOU</span>
 </section><div class="home-links"><a href="#advisor">${icon('spark')}<div><h3>Talk to Lumière</h3><p>A question, a feeling, a little guidance.</p></div>${icon('arrow')}</a><a href="#journey">${icon('chart')}<div><h3>Your skin journal</h3><p>${state.checkins.length?state.checkins.length+' saved check-ins':'Your story begins with one check-in.'}</p></div>${icon('arrow')}</a><button data-action="reminders">${icon('calendar')}<div><h3>Care that keeps in touch</h3><p>${state.settings.remindersEnabled?'Every '+state.settings.intervalDays+' days · in-app':'Choose your check-in rhythm.'}</p></div>${icon('arrow')}</button></div>`;}
function messages(){return state.messages.map(m=>`<div class="conversation-message ${m.role}"><span class="message-by">${m.role==='user'?'YOU':'LUMIÈRE · QWEN3 8B'}</span><div class="message-text">${esc(m.content)}</div>${m.profileUpdates?.length?button('Review profile updates','review-profile',`data-id="${m.id}"`,'outline'):''}${m.productDraft?.name?button('Review product for my shelf','review-product',`data-id="${m.id}"`,'outline'):''}</div>`).join('');}
function advisor(){return `${intro('YOUR BEAUTY ADVISOR','Let’s start with how you feel.')}
 <div class="advisor-layout"><section class="card live-chat"><div class="chat-header"><span class="advisor-avatar">${icon('spark')}</span><div><h3>Lumière</h3><p>Qwen3 8B · running on this computer</p></div></div><div class="live-messages" aria-live="polite">${state.messages.length?messages():`<div class="conversation-message assistant"><span class="message-by">WELCOME</span><p>I’m here to help you find a simple starting point. What feels different about your skin today?</p><div class="quick-prompts">${['My skin feels dry and tight.','I’m new to skincare. Where do I start?','Help me simplify my routine.'].map(p=>`<button data-prompt="${esc(p)}">${p}</button>`).join('')}</div></div>`}${chatBusy?'<div class="thinking" role="status"><i></i>Lumière is considering your question…</div>':''}</div><form data-form="chat" class="chat-composer"><label class="sr-only" for="chat-message">Your message</label><textarea id="chat-message" name="message" rows="3" maxlength="2000" placeholder="Tell me in your own words…" required ${chatBusy?'disabled':''}>${esc(chatDraft)}</textarea><div class="composer-actions"><a class="text-link" href="#checkin">${icon('camera')}Photo check-in</a><button class="button plum" ${chatBusy?'disabled':''}>${chatBusy?'Thinking…':'Send '+icon('arrow')}</button></div></form></section><aside class="advisor-context"><section class="card padded"><span class="eyebrow">WHAT I KNOW ABOUT YOU</span><h3>${esc(name())}</h3><p>${state.profile?esc([state.profile.city,state.profile.life,state.profile.experience].filter(Boolean).join(' · ')):'Your sample name is Jamie Chan. Add only the details you want to share.'}</p><div class="context-memory"><strong>Your focus</strong><span>${esc(state.settings.focus)}</span><strong>Your shelf</strong><span>${state.products.filter(p=>p.status==='using').length} products in use</span><strong>Your journal</strong><span>${state.checkins.length} check-ins</span></div>${link('Edit my profile','profile')}</section><section class="card padded"><h3>Care, with context.</h3><p>Conversations use your saved profile, product feedback and latest check-ins. Photo measurements cannot diagnose a skin condition.</p><p>Persistent or worsening pain, redness or irritation deserves professional advice.</p>${sources.map(s=>`<a class="source-link" target="_blank" rel="noopener" href="${s.url}">${esc(s.name)} ↗</a>`).join('')}</section></aside></div>`;}
function report(r){return `<div class="analysis-report"><span class="eyebrow">EXPERIMENTAL PHOTO OBSERVATIONS</span><h3>${r.quality.usable?'Photo ready for your journal':'A clearer photo would help'}</h3><p>${esc(r.summary)}</p>${r.quality.flags.map(f=>`<p class="notice">${esc(f)}</p>`).join('')}<div class="metric-grid">${[['Brightness',r.metrics.brightness,'Pixel value · 0–255'],['Red-channel intensity',r.metrics.redChannel,'Pixel value · 0–255'],['Cheek red fraction',r.metrics.cheekRedFraction,'Color ratio · 0–1']].map(([n,v,u])=>`<div><span>${n}</span><strong>${v}</strong><small>${u}</small></div>`).join('')}</div><p class="muted">These numbers are not severity scores. Acne, pores, fine lines and hydration are not assessed. Your focus: <strong>${esc(state.settings.focus)}</strong> — use your own observations below to follow it over time.</p></div>`;}
function checkin(){return `${intro('YOUR SKIN MIRROR','How is your skin today?',link('View my journal','journey'))}<section class="card skin-mirror"><div class="scan-copy"><span class="eyebrow">LOOK, LISTEN, UNDERSTAND</span><h2>A photo is a starting point.<br><em>Your feelings tell us more.</em></h2><p>Face the camera in even daylight, without filters. Use the same lighting each time.</p><div class="scan-actions"><label class="button plum">${icon('camera')}Choose a photo<input id="photo-input" type="file" accept="image/jpeg,image/png" hidden></label>${button('Use camera','camera','','outline')}</div><p class="muted">JPG or PNG · Up to 6 MB / 16 MP · Analyzed locally</p></div><div class="scan-preview">${photo?`<img src="${photo.photo}" alt="Your selected photo"><span>LOCAL PHOTO PREVIEW</span>`:`<div class="face-outline">${icon('scan')}</div><span>YOUR PHOTO GOES HERE</span>`}</div></section><div id="analysis-result" aria-live="polite">${photoBusy?'<p class="notice">Analyzing your photo locally…</p>':photo?report(photo.report):''}</div>
 <section class="card padded checkin-form"><span class="eyebrow">BEYOND WHAT A PHOTO CAN TELL</span><h3>Anything feeling uncomfortable?</h3><form data-form="checkin"><div class="form-grid">${select('How does it feel?','feeling',['Dry or tight','Oily','Stinging or itchy','Comfortable','Other'],'Comfortable')}${select('My main focus','focus',['comfort','redness','blemishes','tone'],state.settings.focus)}${[['comfort','Comfort','0 = very uncomfortable · 10 = comfortable'],['redness','Visible redness','0 = none noticed · 10 = very noticeable'],['blemishes','Blemishes','0 = none noticed · 10 = very noticeable'],['tone','Uneven tone','0 = none noticed · 10 = very noticeable']].map(([key,title,hint])=>`<label class="field"><span>${title} <small>· your own rating</small></span><input type="range" min="0" max="10" value="${key==='comfort'?5:0}" name="${key}" oninput="this.nextElementSibling.value=this.value"><output>${key==='comfort'?5:0}</output><small>${hint}</small></label>`).join('')}${textarea('What else would you like to note?','notes','',1200)}</div>${photo?'<label class="check-label"><input type="checkbox" name="keepPhoto">Keep a small copy of this photo in my local journal</label><p class="muted">Unchecked: save the measurements only. The original image is not stored.</p>':''}<div class="form-actions"><button class="button plum" ${photoBusy?'disabled':''}>Save my check-in ${icon('check')}</button><span class="muted">Your ratings are observations, not a diagnosis.</span></div><p class="form-error" role="alert"></p></form></section><a class="journal-link card" href="#journey">${icon('chart')}<div><h3>Your skin journal</h3><p>${state.checkins.length} check-ins · See changes alongside your routine</p></div>${icon('arrow')}</a>`;}
function shelf(){const products=state.products.filter(p=>(period==='all'||p.period===period||p.period==='both')&&(filter==='All'||p.type===filter));const using=state.products.filter(p=>p.status==='using'&&(p.period===period||p.period==='both'));const last=state.settings.lastRoutineVisit;return `${intro('YOUR EVERYDAY ESSENTIALS','A shelf that works for you.',button('＋ Add a product','add-product'))}${tabs(true)}${last&&Date.now()-Date.parse(last)>7*86400000?`<div class="return-banner"><div><h3>Welcome back.</h3><p>Have your skincare habits changed while you were away?</p></div>${button('Let’s catch up','catch-up','','outline')}</div>`:''}<div class="filter-row">${['All','Cleanser','Moisturizer','Sunscreen','Serum','Other'].map(f=>`<button data-filter="${f}" class="${filter===f?'active':''}">${f}</button>`).join('')}</div><div class="shelf-stage">${products.length?products.map(p=>`<button class="shelf-item" data-action="product" data-id="${p.id}">${bottle(p)}<strong>${esc(p.name)}</strong><span>${esc(p.status)} · ${p.period==='both'?'AM + PM':p.period==='morning'?'AM':'PM'}</span><div class="level-track"><i style="width:${remaining(p)}%"></i></div><small>About ${remaining(p)}% left</small></button>`).join(''):empty('Your shelf is ready.','Add the products you actually own. Recommendations stay separate.',button('Add my first product','add-product','','outline'))}</div><p class="muted shelf-note">Bottle levels are rough estimates from your start date and expected use cycle. Update them whenever needed.</p>
 ${period!=='all'?`<section class="card padded"><div class="section-heading"><h2>${period==='morning'?'Morning':'Evening'} care</h2><span>${day()}</span></div>${using.length?`<div class="daily-list">${using.map((p,i)=>{const key=day()+':'+period+':'+p.id;return `<label class="daily-step"><input type="checkbox" data-complete="${p.id}" ${state.completions[key]?'checked':''}><span class="step-number">0${i+1}</span>${icon(p.type==='Sunscreen'?'sun':'bottle')}<span><strong>${esc(p.name)}</strong><small>${esc(p.type)} · Follow the product label</small></span></label>`;}).join('')}</div>${button('Complete my '+(period==='morning'?'morning':'evening')+' care','complete-all')}`:empty('Keep it simple.','Products marked “using” will appear here. Start with what you already tolerate.')}</section>`:`<section class="card padded"><h3>Today, at your pace.</h3><div class="home-links">${['morning','evening'].map(p=>{const list=state.products.filter(x=>x.status==='using'&&(x.period===p||x.period==='both'));return `<button data-period="${p}">${icon(p==='morning'?'sun':'moon')}<div><h3>${p==='morning'?'Morning':'Evening'}</h3><p>${list.filter(x=>state.completions[day()+':'+p+':'+x.id]).length} of ${list.length} steps complete</p></div></button>`;}).join('')}</div></section>`}<section class="catalog-section"><div class="section-heading"><h2>A few basics to explore</h2>${link('Ask for guidance','advisor')}</div><p class="muted">L’Oréal Group product references · Compare your local ingredients and prices. No purchase is made here.</p><div class="catalog-grid">${catalog.map(p=>`<article class="card padded"><span class="eyebrow">${esc(p.brand)}</span><h3>${esc(p.name)}</h3><p>${esc(p.purpose)}</p><p class="muted">${esc(p.note)}</p><a class="source-link" href="${p.url}" target="_blank" rel="noopener">Official product details ↗</a>${button('I own this product','catalog-add',`data-id="${p.id}"`,'outline')}</article>`).join('')}</div></section>`;}
function chart(){const cutoff=span?Date.now()-span*86400000:0;const records=state.checkins.filter(c=>Date.parse(c.at)>=cutoff).sort((a,b)=>Date.parse(a.at)-Date.parse(b.at));if(!records.length)return empty('Your trend starts with a check-in.','A chart appears when you have saved your own ratings.',link('Record how I feel','checkin'));const min=Date.parse(records[0].at),max=Math.max(Date.parse(records.at(-1).at),min+86400000);const x=t=>45+(Date.parse(t)-min)/(max-min)*710,y=v=>220-v*18;const events=state.events.filter(e=>Date.parse(e.at)>=min&&Date.parse(e.at)<=max);return `<svg class="trend-chart" viewBox="0 0 800 270" role="img" aria-label="Self-reported ${metric} on a 0 to 10 scale"><g class="chart-grid">${[0,5,10].map(v=>`<line x1="45" x2="755" y1="${y(v)}" y2="${y(v)}"/><text x="15" y="${y(v)+4}">${v}</text>`).join('')}</g><polyline points="${records.map(c=>`${x(c.at)},${y(c[metric])}`).join(' ')}" fill="none" stroke="var(--sage)" stroke-width="3"/>${records.map(c=>`<circle cx="${x(c.at)}" cy="${y(c[metric])}" r="5" fill="var(--sage)"><title>${longDate(c.at)}: ${c[metric]}/10</title></circle>`).join('')}${events.map(e=>`<g role="button" tabindex="0" aria-label="${esc(e.title)}" data-action="event-detail" data-id="${e.id}"><line x1="${x(e.at)}" x2="${x(e.at)}" y1="45" y2="232" stroke="var(--gold)" stroke-dasharray="4 5"/><circle cx="${x(e.at)}" cy="235" r="7" fill="var(--gold)"/><title>${esc(e.title+' · '+e.detail)}</title></g>`).join('')}<text x="45" y="265">${shortDate(records[0].at)}</text><text x="710" y="265">${shortDate(records.at(-1).at)}</text></svg><p class="muted">Your ${metric==='comfort'?'comfort (higher means more comfortable)':'observed '+metric+' (higher means more noticeable)'}. Gold markers show recorded routine changes. Correlation does not establish a cause.</p>`;}
function journey(){return `${intro('YOUR SKIN JOURNAL','Small changes, seen over time.',button('＋ Record a routine change','add-event','','outline'))}<section class="card padded"><div class="journey-controls"><div class="tabs">${[30,90,0].map(n=>`<button data-span="${n}" class="${span===n?'active':''}">${n?n+' days':'All time'}</button>`).join('')}</div><label class="field"><span>Focus</span><select id="chart-metric">${options(['comfort','redness','blemishes','tone'],metric)}</select></label></div>${chart()}</section><div class="journal-columns"><section class="card padded"><h3>Previous check-ins</h3>${state.checkins.length?[...state.checkins].reverse().map(c=>`<button class="history-row" data-action="checkin-detail" data-id="${c.id}"><span class="history-date">${shortDate(c.at)}</span><span><strong>${esc(c.feeling)}</strong><small>Comfort ${c.comfort}/10${c.analysis?' · Photo observations':''}</small></span>${icon('chevron')}</button>`).join(''):empty('Nothing to compare yet.','Your saved check-ins will live here.')}</section><section class="card padded"><h3>Your routine, in context</h3>${state.events.length?[...state.events].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at)).map(e=>`<button class="history-row" data-action="event-detail" data-id="${e.id}"><span class="history-date">${shortDate(e.at)}</span><span><strong>${esc(e.title)}</strong><small>${esc(e.detail)}</small></span></button>`).join(''):empty('Keep track of what changes.','Record when you start, stop or change a product.')}</section></div>`;}
function weatherPage(){const w=state.weather;const tight=state.checkins.slice(-3).some(c=>c.feeling==='Dry or tight');return `${intro('BY THE WINDOW','A little context for today.')}<section class="weather-card card padded"><div class="weather-head">${icon(w?.isDay===false?'moon':'sun')}<div><span class="eyebrow">${w?esc(w.city.name+', '+w.city.country):'YOUR LOCAL WEATHER'}</span><h2>${w?w.temperature+'°C':'What is it like outside?'}</h2><p>${w?`${esc(w.season)} · ${w.code===0?'Clear':w.code<=3?'Cloudy':w.code>=61?'Precipitation possible':'Mixed conditions'}`:'Choose your city to get today’s conditions.'}</p></div>${button(w?'Refresh weather':'Look up my city','weather-search','','outline')}</div>${w?`<div class="metric-grid"><div><span>Humidity</span><strong>${w.humidity}%</strong></div><div><span>Daily maximum UV</span><strong>${w.uv??'Unavailable'}</strong></div><div><span>Local conditions at</span><strong class="small-value">${esc(w.observedAt.replace('T',' '))}</strong></div></div><p class="muted">Fetched ${longDate(w.fetchedAt)} · ${esc(w.timezone)} · <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>. Forecast values, not personal exposure.</p>`:'<p class="muted">Looking up weather shares your chosen city with Open-Meteo. Your profile and photos stay local.</p>'}</section><section class="card padded"><span class="eyebrow">TODAY’S CARE</span><h3>${w&&w.uv>=3?'Make room for sun protection.':w&&w.humidity<40?'Notice how your skin feels.':'Keep a routine you tolerate.'}</h3><p>${w&&w.uv>=3?'If you go outdoors, use shade and protective clothing, plus a broad-spectrum SPF 30+ sunscreen. Reapply according to its label and your activity.':w&&w.humidity<40?(tight?'You recently mentioned tightness. The reported humidity is low; notice whether your usual moisturizer still feels comfortable.':'The reported humidity is low. A gentle routine and a moisturizer you tolerate may help with dryness.'):'Weather is one part of the picture. Your symptoms and product tolerance matter more than a number.'}</p><div class="form-actions">${link('View my products','shelf')}${link('Record how I feel','checkin')}</div></section>`;}
const blankProfile=()=>({...LumiereProfile.defaults,age:'Prefer not to say',city:'',life:'Prefer not to say',budget:'Ask me each time',routine:'',sensitivities:''});
function profileForm(p=state.profile||blankProfile()){return `<form data-form="profile"><div class="form-grid">${field('Your name','name',p.name,'text','required maxlength="80"')}${field('City (optional)','city',p.city,'text','maxlength="100"')}${Object.entries({age:'Approximate age',life:'Everyday life',experience:'Skincare experience',budget:'Budget preference'}).map(([k,l])=>select(l,k,LumiereProfile.choices[k],p[k])).join('')}${textarea('Your usual routine','routine',p.routine)}${textarea('Sensitivities, preferences or ingredients you avoid','sensitivities',p.sensitivities)}</div><div class="form-actions"><button class="button plum">Save my preferences ${icon('check')}</button></div><p class="form-error" role="alert"></p></form>`;}
function profilePage(){const old=LumiereProfile.createStore(()=>localStorage).load();return `${intro('YOUR SPACE','Your profile. Your choices.')}<div class="journal-columns"><section class="card padded"><div class="profile-heading"><span class="avatar">${esc(name()[0])}</span><div><h3>${esc(name())}</h3><p>${state.profile?'Saved on this computer':'Jamie Chan is a preview profile. Save to personalize your care.'}</p></div></div>${!state.profile&&old.saved?button('Import my previously saved browser profile','import-profile','','outline'):''}${profileForm()}</section><aside><section class="card padded"><span class="eyebrow">A RHYTHM THAT FITS YOUR LIFE</span><h3>Gentle follow-ups</h3><p>${state.settings.remindersEnabled?'Enabled every '+state.settings.intervalDays+' days.':'Currently off. You choose whether to receive check-ins.'}</p>${button('Manage check-ins','reminders','','outline')}</section><section class="card padded"><span class="eyebrow">CARE, WHERE YOU ARE</span><h3>Your familiar apps</h3><p>Messaging connections are still previews.</p>${['WhatsApp','Telegram','WeChat'].map(n=>`<div class="connection-row">${icon('chat')}<div class="connection-copy"><strong>${n}</strong><small>Not connected · Preview only</small></div>${button('Connect','connection',`data-provider="${n}"`,'outline')}</div>`).join('')}</section><section class="card padded"><span class="eyebrow">FIRST-VISIT PREVIEW</span><h3>See the welcome again.</h3><p>Reset the welcome screen whenever you want to demo the first-time experience. Your profile, chats and journal stay saved.</p>${button('Show first-time welcome','reset-welcome','','outline')}</section><section class="card padded"><span class="eyebrow">YOUR DATA</span><h3>Local, and in your control.</h3><p>One local profile on this computer. Chats, journal entries and product feedback are stored in the project’s data folder. This demo has no cloud account.</p><div class="form-actions">${button('Export my data','export','','outline')}${button('Delete my data','delete','','outline')}</div></section></aside></div>`;}
function render(){if(!state)return;navClose();const page=route()==='routine'?'shelf':route();const pages={overview,advisor,checkin,shelf,journey,profile:profilePage,weather:weatherPage};document.body.classList.toggle('evening',period==='evening'&&(page==='shelf'||(page==='overview'&&state.settings.onboarded)));main.innerHTML=(pages[page]||overview)();$('#page-label').textContent=({overview:'My dressing table',advisor:'Beauty advisor',checkin:'Skin mirror',shelf:'My product shelf',journey:'My skin journal',profile:'My profile',weather:'By the window'})[page]||'My dressing table';document.querySelectorAll('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===page));document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));identity();if(page==='advisor')$('.live-messages').scrollTop=$('.live-messages').scrollHeight;}
function productForm(p={}){const value={name:'',type:'Moisturizer',period:'both',status:'using',start:day(),cycleDays:60,remaining:100,purpose:'',notes:'',...p};modal(p.id?'Edit your product':'Add to your shelf',`<p>Only record products you actually own. Nothing is purchased here.</p><form data-form="product"><input type="hidden" name="id" value="${esc(p.id||'')}"><div class="form-grid">${field('Product name','name',value.name,'text','required maxlength="120"')}${select('Product type','type',['Cleanser','Moisturizer','Sunscreen','Serum','Other'],value.type)}${select('When you use it','period',['morning','evening','both'],value.period)}${select('Current status','status',['purchased','using','paused','finished'],value.status)}${field('Start / purchase date','start',value.start,'date','required max="'+day()+'"')}${field('Estimated full-bottle duration (days)','cycleDays',value.cycleDays,'number','min="7" max="730" required')}${field('How much is left now? (%)','remaining',p.id?remaining(p):value.remaining,'number','min="0" max="100" required')}${field('What you use it for','purpose',value.purpose,'text','maxlength="300"')}${textarea('Notes / reason for this change','notes',value.notes)}</div><p class="muted">Duration is a rough estimate, not a recommended usage frequency. Follow the label.</p><label class="check-label"><input type="checkbox" required>I confirm this product and its current use status.</label><button class="button plum">Save product</button><p class="form-error" role="alert"></p></form>`);}
function productDetail(id){const p=state.products.find(p=>p.id===id);if(!p)return;modal(esc(p.name),`<div class="product-detail-visual">${bottle(p,true)}<div><strong class="remaining-number">~${remaining(p)}%</strong><p>estimated remaining</p><small>${p.cycleDays}-day full-bottle estimate</small></div></div><div class="detail-facts"><p><strong>Status</strong>${esc(p.status)}</p><p><strong>Started</strong>${esc(p.start)}</p><p><strong>Routine</strong>${esc(p.period)}</p><p><strong>Purpose</strong>${esc(p.purpose||'Not specified')}</p></div>${button('Edit product or usage','edit-product',`data-id="${p.id}"`,'outline')}<h3 class="modal-section">How does it feel?</h3><form data-form="feedback"><input type="hidden" name="id" value="${p.id}">${select('Your experience','feeling',['Comfortable','Sticky','Dry','Stinging or discomfort','No clear change','Other'],'Comfortable')}${textarea('A little more detail (optional)','notes')}<button class="button plum">Save feedback</button><p class="form-error" role="alert"></p></form><p class="muted">If a product stings or irritates, stop using it and seek advice if symptoms persist or worsen.</p><h3 class="modal-section">Check your bottle</h3><div class="quick-prompts">${[['enough','Still enough'],['low','Running low'],['finished','Finished'],['paused','Stopped using']].map(([v,l])=>`<button data-action="bottle-state" data-id="${p.id}" data-value="${v}">${l}</button>`).join('')}</div>${p.feedback.length?`<details><summary>Previous feedback (${p.feedback.length})</summary>${p.feedback.slice().reverse().map(f=>`<p>${shortDate(f.at)} · ${esc(f.feeling)}<br>${esc(f.notes)}</p>`).join('')}</details>`:''}`);}
function reminders(){modal('A little check-in, on your terms.',`<p>Reminders appear in this app. The local server must be running; overdue check-ins are picked up when it restarts. This version does not send WhatsApp, Telegram or WeChat messages.</p><form data-form="reminders"><label class="check-label"><input type="checkbox" name="enabled" ${state.settings.remindersEnabled?'checked':''}>Enable gentle follow-ups</label><div class="form-grid">${select('Regular check-in frequency','intervalDays',['3','7','14','30'],String(state.settings.intervalDays))}${field('Earliest delivery hour (8–20)','hour',state.settings.hour,'number','min="8" max="20" required')}${field('Timezone','timezone',state.settings.timezone,'text','required maxlength="80"')}</div><p class="muted">Also check in 3 days after a product is purchased or started, and when its estimated level is low. Quiet hours: 9 pm until your chosen hour.</p><button class="button plum">Save follow-up preferences</button><p class="form-error" role="alert"></p></form>`);}
function eventForm(){modal('A change worth remembering.',`<form data-form="event"><div class="form-grid">${field('What changed?','title','','text','required maxlength="120"')}${field('When?','date',day(),'date','required max="'+day()+'"')}${textarea('Product, frequency, purpose or how it felt','detail')}</div><button class="button plum">Save to my journal</button><p class="form-error" role="alert"></p></form>`);}
async function analyzeFile(file){if(!file||photoBusy)return;if(file.size>6*1024*1024)throw Error('Choose an image under 6 MB.');if(!['image/jpeg','image/png'].includes(file.type))throw Error('Choose a JPG or PNG.');photoBusy=true;photo=null;render();try{const image=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the photo.'));reader.readAsDataURL(file);});photo=await api('analyze',{image});toast('Photo analyzed locally. Add how you feel, then save your check-in.');}finally{photoBusy=false;render();}}
async function camera(){modal('A moment in the mirror.',`<video id="camera-preview" autoplay playsinline muted></video><p>Find even daylight. Photos are processed locally.</p><div class="form-actions">${button('Take photo','capture')}${button('Cancel','close-dialog','','outline')}</div><p id="camera-error" role="alert"></p>`);try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:1280}},audio:false});if(!dialog.open){stream.getTracks().forEach(t=>t.stop());stream=null;return;}$('#camera-preview').srcObject=stream;}catch{$('#camera-error').textContent='Camera access is unavailable or was declined. You can upload a photo instead.';}}
const actions={
 'menu':navOpen,'close-menu':()=>{navClose();$('.menu-toggle').focus();},'close-dialog':closeModal,
 start:async()=>{await api('settings',{onboarded:true});location.hash='advisor';render();},skip:async()=>{await api('settings',{onboarded:true});render();},
 'reset-welcome':async()=>{await api('settings',{onboarded:false});location.hash='overview';render();toast('First-time welcome is ready. Your saved data is still here.');},
 'shelf-am':()=>{period='morning';location.hash='shelf';render();},'shelf-pm':()=>{period='evening';location.hash='shelf';render();},
 'add-product':()=>productForm(),product:b=>productDetail(b.dataset.id),'edit-product':b=>productForm(state.products.find(p=>p.id===b.dataset.id)),
 'catalog-add':b=>{const p=catalog.find(p=>p.id===b.dataset.id);productForm({name:p.name,type:p.type,purpose:p.purpose});},
 'review-product':b=>productForm(state.messages.find(m=>m.id===b.dataset.id).productDraft),
 'review-profile':b=>{const m=state.messages.find(m=>m.id===b.dataset.id),p={...(state.profile||blankProfile())};for(const update of m.profileUpdates)p[update.field]=update.value;modal('Review what Lumière understood.',`<p>Check these proposed details before saving. Your current profile has not changed.</p>${profileForm(p)}`);},
 'import-profile':async()=>{const old=LumiereProfile.createStore(()=>localStorage).load();if(!old.saved)throw Error('No saved browser profile found.');await api('profile',old.data);render();toast('Your previous profile is now saved with the local companion.');},
 'complete-all':async()=>{await api('complete',{period,all:true,done:true});render();toast('Your routine is recorded for today.');},
 'add-event':eventForm,
 'event-detail':b=>{const e=state.events.find(e=>e.id===b.dataset.id);modal(esc(e.title),`<p class="eyebrow">${longDate(e.at)}</p><p class="preserve-lines">${esc(e.detail)}</p>${e.productId?button('Open product','product',`data-id="${e.productId}"`,'outline'):''}`);},
 'checkin-detail':b=>{const c=state.checkins.find(c=>c.id===b.dataset.id);modal('Your check-in · '+shortDate(c.at),`${c.photo?`<img class="journal-photo" src="${c.photo}" alt="Photo saved with this check-in">`:''}<p><strong>${esc(c.feeling)}</strong> · Comfort ${c.comfort}/10</p><p>Self-reported redness ${c.redness}/10 · blemishes ${c.blemishes}/10 · uneven tone ${c.tone}/10</p><p class="preserve-lines">${esc(c.notes)}</p>${c.analysis?report(c.analysis):''}`);},
 reminders,
 notifications:()=>modal('A little note from Lumière.',`${state.notifications.length?state.notifications.slice().reverse().map(n=>`<article class="notification-entry ${n.read?'read':''}"><span class="eyebrow">${longDate(n.at)}${n.read?' · READ':''}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p>${n.productId?button('Open product','product',`data-id="${n.productId}"`,'outline'):link('Record a check-in','checkin')}${!n.read?button('Mark read','read-notification',`data-id="${n.id}"`,'outline'):''}</article>`).join(''):empty('Nothing waiting for you.','Enable follow-ups to receive a gentle in-app check-in.')}${button('Manage follow-ups','reminders','','outline')}`),
 'read-notification':async b=>{await api('notification',{id:b.dataset.id});identity();actions.notifications();},
 connection:b=>modal(`${esc(b.dataset.provider)}, when you’re ready.`,`<p>This connection remains a UI preview. A real integration needs a provider account, approved credentials and a public webhook service. No account is linked and no message is sent.</p>`),
 'weather-search':async()=>{modal('Choose your city.',`<form data-form="city">${field('City','city',state.profile?.city||'','text','required maxlength="100"')}<p class="muted">Your search goes to Open-Meteo. No precise device location is requested.</p><button class="button plum">Search cities</button><p class="form-error" role="alert"></p></form><div id="city-options"></div>`);},
 'weather-city':async b=>{b.disabled=true;b.textContent='Loading weather…';await api('weather',{id:Number(b.dataset.id)});closeModal();render();},
 'bottle-state':async b=>{const p=state.products.find(p=>p.id===b.dataset.id);if(b.dataset.value==='enough'){productForm({...p,remaining:remaining(p)});return;}const value=b.dataset.value;await api('product',{...p,status:value==='low'?p.status:value,remaining:value==='finished'?0:value==='low'?10:remaining(p)});modal('Thank you for updating your shelf.',`<p>${value==='low'?'Your bottle is marked as running low.':value==='finished'?'Your bottle is marked as finished.':'This product is marked as paused.'}</p><div class="quick-prompts">${button('Continue with a new bottle','refill',`data-id="${p.id}"`,'outline')}<button data-action="alternatives" data-id="${p.id}">Explore alternatives</button><button data-action="close-dialog">Not now</button></div>`);render();},
 refill:b=>{const p=state.products.find(p=>p.id===b.dataset.id);productForm({...p,id:undefined,createdAt:undefined,start:day(),remaining:100,status:'using',notes:'New bottle of the same product.'});},
 alternatives:b=>{const p=state.products.find(p=>p.id===b.dataset.id);chatDraft=`Help me compare alternatives to ${p.name}, using my preferences and product feedback.`;closeModal();location.hash='advisor';render();},
 'catch-up':()=>modal('Welcome back. How has it been?',`<p>Have your skincare habits changed?</p><div class="quick-prompts vertical">${[['same','Mostly following my plan'],['forgot','Sometimes I forget'],['changed','I changed a product'],['paused','I paused some steps'],['skip','I’m not sure — skip']].map(([v,l])=>`<button data-action="catch-answer" data-value="${v}">${l}</button>`).join('')}</div>`),
 'catch-answer':async b=>{const v=b.dataset.value;if(v==='forgot'){modal('How often do you forget?',`<div class="quick-prompts vertical">${['Occasionally','A few times a week','Often','Not sure'].map(l=>`<button data-action="catch-frequency" data-value="${l}">${l}</button>`).join('')}</div>`);return;}if(v==='changed'||v==='paused'){modal(v==='changed'?'Which product changed?':'Which step did you pause?',`<p>Edit the product’s status, frequency and notes. The change will appear in your journal.</p><div class="quick-prompts vertical">${state.products.map(p=>`<button data-action="edit-product" data-id="${p.id}">${esc(p.name)}</button>`).join('')}${button('Add a replacement product','add-product','','outline')}</div>`);return;}await api('event',{title:'Routine catch-up',detail:v==='same'?'Mostly following my plan.':'Skipped recall; no adherence inferred.',date:day()});closeModal();render();},
 'catch-frequency':async b=>{await api('event',{title:'Routine catch-up',detail:'Missed routine: '+b.dataset.value,date:day()});closeModal();render();},
 camera,
 capture:async()=>{const v=$('#camera-preview');if(!v.videoWidth)throw Error('Wait for the camera to be ready.');const canvas=document.createElement('canvas');canvas.width=v.videoWidth;canvas.height=v.videoHeight;canvas.getContext('2d').drawImage(v,0,0);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.9));closeModal();await analyzeFile(new File([blob],'camera.jpg',{type:'image/jpeg'}));},
 export:()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='lumiere-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},
 delete:()=>modal('Delete your local companion data?',`<p>This removes your saved profile, chats, check-ins, retained photos, product shelf and reminders from this app. It also removes the previous profile stored by this browser. Export first if you want a copy.</p><form data-form="delete">${field('Type DELETE to confirm','confirm','','text','required pattern="DELETE"')}<button class="button plum">Delete my data</button><p class="form-error" role="alert"></p></form>`)
};
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');try{if(a){await actions[a.dataset.action]?.(a);return;}const p=e.target.closest('[data-period]');if(p){period=p.dataset.period;render();return;}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();return;}const s=e.target.closest('[data-span]');if(s){span=Number(s.dataset.span);render();return;}const prompt=e.target.closest('[data-prompt]');if(prompt){chatDraft=prompt.dataset.prompt;$('#chat-message').value=chatDraft;$('#chat-message').focus();}}catch(error){toast(error.message);if(a)a.disabled=false;}});
document.addEventListener('input',e=>{if(e.target.id==='chat-message')chatDraft=e.target.value;});
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();});
document.addEventListener('change',async e=>{try{if(e.target.id==='photo-input')await analyzeFile(e.target.files[0]);if(e.target.id==='chart-metric'){metric=e.target.value;render();}if(e.target.dataset.complete){await api('complete',{period,id:e.target.dataset.complete,done:e.target.checked});toast('Routine updated.');}}catch(error){toast(error.message);if(e.target.dataset.complete)e.target.checked=!e.target.checked;}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const type=form.dataset.form,b=Object.fromEntries(new FormData(form)),submit=form.querySelector('button[type="submit"],button:not([type])'),err=form.querySelector('.form-error');if(err)err.textContent='';if(submit)submit.disabled=true;try{
 if(type==='chat'){chatBusy=true;chatDraft=b.message;render();await api('chat',{message:b.message});chatDraft='';chatBusy=false;render();return;}
 if(type==='profile'){await api('profile',b);closeModal();toast('Your preferences are saved.');}
 if(type==='product'){if(!b.id)delete b.id;await api('product',b);closeModal();toast('Product saved to your shelf and journal.');}
 if(type==='feedback'){await api('feedback',b);closeModal();toast('Your feedback is saved.');}
 if(type==='event'){await api('event',b);closeModal();toast('Change added to your journal.');}
 if(type==='checkin'){await api('checkin',{...b,analysisId:photo?.analysisId,keepPhoto:b.keepPhoto==='on'});await api('settings',{focus:b.focus,onboarded:true});photo=null;metric=b.focus;toast('Your check-in is saved.');location.hash='journey';}
 if(type==='reminders'){await api('settings',{remindersEnabled:b.enabled==='on',intervalDays:Number(b.intervalDays),hour:Number(b.hour),timezone:b.timezone});closeModal();toast('Follow-up preferences saved.');}
 if(type==='city'){const d=await api('cities',b);$('#city-options').innerHTML=d.cities.length?d.cities.map(c=>`<button class="history-row" data-action="weather-city" data-id="${c.id}"><span><strong>${esc(c.name)}</strong><small>${esc(c.region+', '+c.country)}</small></span>${icon('arrow')}</button>`).join(''):'<p>No cities found. Try another spelling.</p>';return;}
 if(type==='delete'){await api('delete',b);try{localStorage.removeItem(LumiereProfile.key);}catch{}photo=null;chatDraft='';closeModal();location.hash='overview';toast('Local companion data deleted.');}
 render();
 }catch(error){if(type==='chat'){chatBusy=false;render();toast(error.message);}else if(err)err.textContent=error.message;else toast(error.message);}finally{if(submit)submit.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.target.matches('svg [role="button"]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(!$('.sidebar').classList.contains('open'))return;if(e.key==='Escape'){navClose();$('.menu-toggle').focus();}if(e.key==='Tab'){const items=[...$('.sidebar').querySelectorAll('a,button')].filter(x=>x.getClientRects().length);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}});
dialog.addEventListener('close',()=>{if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}});
window.addEventListener('hashchange',()=>{closeModal();render();main.focus({preventScroll:true});});
async function checkStatus(){try{status=await api('status');$('#model-status').textContent=status.ready?'Qwen3 8B · Local':'Qwen3 8B · Offline';$('#model-status').classList.toggle('online',status.ready);}catch{$('#model-status').textContent='Local server unavailable';}}
async function init(){try{const d=await api('bootstrap');token=d.token;catalog=d.catalog;sources=d.sources;metric=state.settings.focus;render();await checkStatus();}catch(error){main.innerHTML=`<section class="card padded"><h1>Let’s reconnect.</h1><p>${esc(error.message)}</p><p>Start the local server with Start Lumiere.cmd, then reload this page.</p></section>`;}}
setInterval(async()=>{await checkStatus();try{const d=await api('bootstrap');token=d.token;identity();}catch{}},60000);
init();
